    ["Opening line for a named character"] = "Ligne d’ouverture pour un personnage nommé",
    ["Opening line for an ordinary person"] = "Ligne d’ouverture pour une personne ordinaire",
    ["Closing line"] = "Ligne de fin",
    ["Closing line for a speaker with a reply length of its own"] = "Ligne de fermeture pour un locuteur ayant une longueur de réponse propre",
    ["Temperature"] = "Température",
    ["Top P"] = "Top P",
    ["Repeat penalty"] = "Pénalité répétition",
    ["Longest reply (in tokens)"] = "Réponse la plus longue (en tokens)",
    ["Top K"] = "Top K",
    ["Min P"] = "Min P",
    ["Presence penalty"] = "Pénalité de présence",
    ["Frequency penalty"] = "Pénalité de fréquence",
    ["Advanced parameters (JSON)"] = "Paramètres avancés (JSON)",
    ["Extra settings added to every reply, written as a JSON object, for example {example}. Use it for samplers that have no box above. A setting that has its own box above is refused. If a server refuses a setting, it is left out and the reply still comes."] = "Réglages supplémentaires ajoutés à chaque réponse, écrits sous forme d’objet JSON, par exemple {example}. À utiliser pour les samplers qui n’ont pas de case ci-dessus. Un réglage qui a sa propre case ci-dessus est refusé. Si un serveur refuse un réglage, il est ignoré et la réponse arrive quand même.",
    ["Mistral takes only the settings shown here. Top K, Min P and the advanced JSON are for Local AI and Custom models."] = "Mistral n’accepte que les réglages affichés ici. Top K, Min P et le JSON avancé sont pour les modèles Local AI et personnalisés.",
    ["Mistral does not take this setting."] = "Mistral n’accepte pas ce réglage.",
    ["That is not valid JSON."] = "Ce n’est pas du JSON valide.",
    ["This must be a JSON object, for example {example}."] = "Il doit s’agir d’un objet JSON, par exemple {example}.",
    ["Too many keys. Keep {max} or fewer."] = "Trop de clés. Gardez {max} ou moins.",
    ["“{name}” is not a usable key name. Use letters, digits and underscores."] = "“{name}” n’est pas un nom de clé utilisable. Utilisez des lettres, des chiffres et des tirets bas.",
    ["“{name}” has its own setting in this form. Use that instead."] = "“{name}” a son propre réglage dans ce formulaire. Utilisez celui-là à la place.",
    ["Use the Longest reply box for the length of a reply, not “{name}”."] = "Utilisez la case Réponse la plus longue pour la longueur d’une réponse, pas “{name}”.",
    ["“{name}” is set by the mod and cannot be changed here."] = "“{name}” est défini par le mod et ne peut pas être modifié ici.",
    ["“{name}” needs a number, a text, true or false, or a list of those."] = "“{name}” attend un nombre, un texte, vrai ou faux, ou une liste de ces valeurs.",
    ["Longest character description, in characters"] = "Description de personnage la plus longue, en caractères",
    ["Earlier turns kept"] = "Tours précédents gardés",
    ["Right-now sentence"] = "Phrase du moment",
    ["Notes for this turn"] = "Notes pour ce tour",
    ["That prompting option was not found."] = "Cette option de prompt est introuvable.",
    ["Keep at least one rule."] = "Gardez au moins une règle.",
    ["Rule {n} is empty. Write the rule or delete it."] = "La règle {n} est vide. Écrivez la règle ou supprimez-la.",
    ["Rule {n} is too long. Keep each one under {max} characters."] = "La règle {n} est trop longue. Gardez chacune sous {max} caractères.",
    ["The rules are too long together. Keep them under {max} characters in all."] = "Les règles sont trop longues ensemble. Gardez-les sous {max} caractères au total.",
    ["This text is too long. Keep it under {max} characters."] = "Ce texte est trop long. Gardez-le sous {max} caractères.",
    ["This text cannot be empty."] = "Ce texte ne peut pas être vide.",
    ["Use a number from {min} to {max}."] = "Utilisez un nombre de {min} à {max}.",
    ["Too many stop texts. Keep {max} or fewer."] = "Trop de textes d’arrêt. Gardez {max} ou moins.",
    ["A stop text is too long. Keep each one under {max} characters."] = "Un texte d’arrêt est trop long. Gardez chacun sous {max} caractères.",
    ["{field}: {message}"] = "{field} : {message}",
    ["In use now"] = "En cours",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "Comment chaque option de conversation doit répondre. Chaque option a son propre prompt. Une modification compte à partir de la réponse suivante, sans rien redémarrer.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "Les faits que les personnages reçoivent du jeu et une courte liste de filtres de sécurité ne peuvent pas être modifiés ici. Le prompt de Convai se trouve du côté de Convai.",
    ["Mistral and Local AI"] = "Mistral et Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite et Standard sont les deux tailles de modèle Local AI. « Adulte activé » est utilisé quand le contenu pour adultes est activé.",
    ["Your Custom models and APIs"] = "Vos modèles et API personnalisés",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "Un modèle personnalisé apparaît ici une fois que vous choisissez Personnalisé comme fournisseur de conversation et que vous définissez un modèle.",
    ["From {min} to {max}."] = "De {min} à {max}.",
    ["Shipped: {value}"] = "D’origine : {value}",
    ["Rule {n}"] = "Règle {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "Règle {n}, pour un locuteur ayant une longueur de réponse propre",
    ["Rule {n}, for Mature content"] = "Règle {n}, pour le contenu pour adultes",
    ["Move rule {n} up"] = "Monter la règle {n}",
    ["Move up"] = "Monter",
    ["Move rule {n} down"] = "Descendre la règle {n}",
    ["Move down"] = "Descendre",
    ["Delete rule {n}"] = "Supprimer règle {n}",
    ["Other versions of this rule"] = "Autres versions de cette règle",
    ["Leave a version empty to use the rule text."] = "Laissez une version vide pour utiliser le texte de la règle.",
    ["For a speaker with a reply length of its own"] = "Pour un locuteur ayant une longueur de réponse propre",
    ["For Mature content"] = "Pour adultes",
    ["Shipped: off"] = "D’origine : non",
    ["Shipped: the mod’s own limit"] = "D’origine : la limite propre au mod",
    ["before V’s words"] = "avant les mots de V",
    ["after V’s words"] = "après les mots de V",
    ["Repeat the “where you are” sentence right before V’s words"] = "Répéter la phrase « où vous êtes » juste avant les mots de V",
    ["The notes for this turn go"] = "Les notes pour ce tour vont",
    ["Output rules"] = "Règles de sortie",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "Les règles numérotées que le modèle lit avant chaque réponse. Utilisez {name} pour le nom du personnage et {words} pour la longueur de réponse d’un locuteur qui en a une.",
    ["Example replies"] = "Exemples de réponses",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "Réponses montrées au modèle après les règles. Un petit modèle peut les recopier mot pour mot : n’en ajoutez aucune, ou gardez-les courtes et simples.",
    ["Add an example reply"] = "Ajouter un exemple",
    ["An example reply"] = "Un exemple de réponse",
    ["Example reply {n}"] = "Exemple de réponse {n}",
    ["Opening line"] = "Ligne d’ouverture",
    ["The first line of the character text. Use {name} for the character’s name."] = "La première ligne du texte du personnage. Utilisez {name} pour le nom du personnage.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "Le dernier élément que lit le modèle avant de répondre. Utilisez {name} pour le nom du personnage et {words} pour la longueur de réponse. Le réglage pour adultes ajoute sa propre clause après.",
    ["Section headings"] = "Titres de section",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "Les titres qui marquent chaque partie du prompt. Modifiez la formulation, pas l’ordre.",
    ["Layout"] = "Disposition",
    ["Where some notes go in the prompt."] = "Où certaines notes vont dans le prompt.",
    ["Sampling"] = "Échantillon",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "La liberté avec laquelle le modèle formule sa réponse. Laissez une case vide pour utiliser la valeur d’origine.",
    ["Length limits"] = "Limites de taille",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "Raccourcit ce que lit le modèle, ce qui rend les réponses plus rapides. Les limites propres au mod restent appliquées, donc celles-ci ne peuvent que raccourcir.",
    ["Stop texts"] = "Textes d’arrêt",
    ["Mature layer"] = "Couche pour adultes",
    ["The crude, forward wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "Les formulations crues et directes ajoutées quand le Contenu pour adultes est activé. Le mod choisit la version explicite ou suggestive d’une réplique selon ce que permet le modèle chargé, alors modifiez la version que votre modèle utilise. Une case vidée retire cette réplique. La ligne réservée aux adultes et les limites strictes sont toujours ajoutées en dernier et ne peuvent pas être modifiées.",
    ["Speech line"] = "Réplique",
    ["Word bank"] = "Banque de mots",
    ["Romance line"] = "Réplique romantique",
    ["Closing clause"] = "Formule de fin",
    ["Tone line"] = "Ligne de ton",
    ["Partner paragraph: affection and desire"] = "Paragraphe partenaire : affection et désir",
    ["Partner paragraph: nothing invented"] = "Paragraphe partenaire : rien d’inventé",
    ["{part}, for models that allow explicit sex"] = "{part}, pour les modèles qui autorisent le sexe explicite",
    ["{part}, for models that keep sex suggestive"] = "{part}, pour les modèles qui gardent le sexe suggestif",
    ["This option does not get the Mature layer."] = "Cette option ne reçoit pas la couche pour adultes.",
    ["Mature layer and closing line, for models that allow explicit sex"] = "Couche pour adultes et ligne de fin, pour les modèles qui autorisent le sexe explicite",
    ["Mature layer and closing line, for models that keep sex suggestive"] = "Couche pour adultes et ligne de fin, pour les modèles qui gardent le sexe suggestif",
    ["A reply ends when the model writes one of these. Line breaks count. Up to {max}."] = "Une réponse se termine quand le modèle écrit l’un de ces textes. Les sauts de ligne comptent. Jusqu’à {max}.",
    ["Add a stop text"] = "Ajouter un arrêt",
    ["A text that ends the reply"] = "Un texte qui termine la réponse",
    ["Stop text {n}"] = "Texte d’arrêt {n}",
    ["Preview"] = "Aperçu",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "Le texte du prompt tel que le modèle le lirait pour un personnage exemple. Il suit vos modifications pendant la saisie, avant l’enregistrement.",
    ["Sample character name"] = "Nom du personnage exemple",
    ["A speaker with a reply length of its own"] = "Un locuteur ayant une longueur de réponse propre",
    ["Reply length in words"] = "Longueur de réponse en mots",
    ["Mature content is on"] = "Contenu adulte activé",
    ["The preview waits until the problems in the form are fixed."] = "L’aperçu attend que les problèmes du formulaire soient corrigés.",
    ["No example replies."] = "Aucun exemple de réponse.",
    ["No closing line."] = "Pas de ligne de fin.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "Revenir au prompt d’origine de {name} ? Vos modifications sur cette partie seront supprimées.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "Revenir au prompt d’origine de {name} ? Toutes vos modifications seront supprimées.",
    ["Back to the shipped prompting."] = "Revenir au prompt d’origine.",
    ["Prompting"] = "Prompt",
    ["Street reputation"] = "Réputation de rue",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "Les gangs, le NCPD, les corporations et les habitants de chaque district se souviennent de ce que V a fait : Street Cred, choix en mission, combats, crimes vus par la police, façon de traiter les gens. Cela guide leur accueil, leur confiance et leur aide.\n\nSeulement les gens ordinaires, jamais les personnages nommés ou de l’histoire. Change leurs mots, rien dans le jeu.",
    ["Voice language"] = "Langue de la voix",
    ["English"] = "Anglais",
    ["Automatic"] = "Automatique",
    ["Polish"] = "Polonais",
    ["Russian"] = "Russe",
    ["Ukrainian"] = "Ukrainien",
    ["Turkish"] = "Turc",
    ["Czech"] = "Tchèque",
    ["Hungarian"] = "Hongrois",
    ["Japanese"] = "Japonais",
    ["Korean"] = "Coréen",
    ["Chinese"] = "Chinois",
    ["Choose one of the listed reply languages."] = "Choisissez l’une des langues de réponse proposées.",
    ["The language the characters speak. Counts only while Voice playback is on; with it off, replies follow what you write.\n\nAutomatic: follows what you write or say, and never changes on a short line.\n\nA voice that cannot speak the language shows the reply as text."] = "La langue que parlent les personnages. Ne compte que lorsque la Lecture vocale est activée ; désactivée, les réponses suivent ce que vous écrivez.\n\nAutomatique : suit ce que vous écrivez ou dites, et ne change jamais sur une réplique courte.\n\nUne voix qui ne peut pas parler cette langue affiche la réponse en texte.",
    ["No speech was heard. Hold the talk key while you speak."] = "Aucune parole entendue. Maintenez la touche vocale enfoncée pendant que vous parlez.",
    ["Voice activation"] = "Activation vocale",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "L'activation vocale n'a pas pu ouvrir le microphone. Vérifiez votre périphérique d'entrée Windows.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "L'entrée vocale n'a pas pu joindre Convai. Maintenez de nouveau la touche vocale enfoncée, ou tapez.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Parlez sans maintenir de touche. Face à un personnage ou si un compagnon est proche, le mod vous écoute et répond après une pause d'environ une seconde.\n\nJamais pendant les scènes ou choix de dialogue du jeu, ni pendant qu'un personnage parle. Rien ne quitte votre PC sans parole entendue. Le casque est recommandé ; un micro Bluetooth le passe en qualité d'appel pendant l'écoute.",
    ["Opening microphone…"] = "Ouverture du microphone…",
    ["Speak now"] = "Parlez maintenant",
    ["Controller talk button"] = "Bouton de parole manette",
    ["Talk with a controller: hold the left stick click (L3) at a character, speak, and let go to send. Hold it with the stick at rest.\n\nOn foot only, never in menus, scenes, dialogue choices, calls, combat or a vehicle. The click still toggles sprint, which does nothing while you stand."] = "Parlez avec la manette : maintenez le clic du stick gauche (L3) sur un personnage, parlez, puis relâchez pour envoyer. Maintenez-le avec le stick au repos.\n\nÀ pied uniquement, jamais dans les menus, les scènes, les choix de dialogue, les appels, le combat ou un véhicule. Le clic bascule quand même le sprint, sans effet à l'arrêt.",
    ["V speaks your microphone lines"] = "V dit vos répliques du micro",
    ["After you speak (hold to talk or Voice activation), V says your words out loud in V’s voice, and the reply follows V’s line. Needs V’s voice on. Off by default, because you just said it yourself."] = "Après que vous avez parlé (maintenez la touche vocale ou Activation vocale), V dit vos mots à voix haute, avec la voix de V, et la réponse suit la réplique de V. Nécessite que la voix de V soit activée. Désactivé par défaut, car vous venez de les dire vous-même.",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Saisissez du texte dans la zone de recherche pour trouver un modèle par son nom ou son enregistrement, par exemple « rita wheeler ». Une partie d’un mot suffit.",
    ["Content packs"] = "Paquets de contenu",
    ["Add-ons that change how the characters talk."] = "Modules complémentaires qui changent la façon dont les personnages parlent.",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Mistral, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "Active ou désactive le paquet de contenu {name}. Un paquet change la façon dont les personnages parlent. Ses modifications de prompt fonctionnent avec Mistral, Local AI et Personnalisé. Sur Convai, ses règles du monde et ses propres personnages Convai s’appliquent. Un changement compte à partir de la prochaine réponse, les nouveaux noms après un redémarrage.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "Les paquets de contenu ajoutent des règles après les vôtres. Vous ne pouvez pas les modifier ici : désactivez un paquet dans Paramètres > Paquets de contenu, dans le jeu.",
    ["From the content pack {name}"] = "Depuis le paquet de contenu {name}",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Paquets de contenu qui modifient ce prompt : {names}. Vos propres modifications restent au-dessus des leurs, et Réinitialiser par défaut rétablit le texte du paquet.",
    ["Memory in use"] = "Souvenirs utilisés",
    ["Normal memory"] = "Souvenirs normaux",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Effacer les souvenirs ne supprime que les souvenirs affichés ici. Les autres souvenirs restent tels quels.",
    ["This clears the memory in use: {memory}."] = "Cela efface les souvenirs utilisés : {memory}.",
    ["Backspace"] = "Retour arrière",
    ["Cancelled."] = "Annulé.",
    ["Caps lock"] = "Verr. Maj.",
    ["Choose a key or a controller button."] = "Choisissez une touche ou un bouton de manette.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Choisissez les touches et boutons de manette pour parler à la voix ou au texte, les discussions de groupe et la gestion des compagnons. Ils fonctionnent tout de suite.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Choisissez les touches et boutons de manette pour les actions du mod. Appuyez sur Définir, puis sur la touche ou le bouton voulu. Esc ou B annule. Un changement prend effet tout de suite, et les touches définies dans Cyber Engine Tweaks restent actives. Choisissez des touches que le jeu n’utilise pas encore.",
    ["Controller"] = "Manette",
    ["Controller {button}"] = "Manette : {button}",
    ["D-pad down"] = "Croix bas",
    ["D-pad left"] = "Croix gauche",
    ["D-pad right"] = "Croix droite",
    ["D-pad up"] = "Croix haut",
    ["Down arrow"] = "Flèche bas",
    ["End"] = "Fin",
    ["Enter"] = "Enter",
    ["Group text chat"] = "Groupe : texte",
    ["Group voice chat"] = "Groupe : voix",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Maintenez-la pour parler à tous les personnages autour de vous en même temps, et relâchez pour envoyer. Si vous ne regardez personne, vous parlez au premier membre de votre groupe et à deux autres membres du groupe.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Maintenez-la pour parler à Johnny, la voix dans votre tête, quel que soit l’endroit où vous regardez, et relâchez pour envoyer. Johnny dans votre tête doit être activé dans les Paramètres.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Maintenez la touche ou le bouton pendant que vous parlez, et relâchez pour envoyer, comme la touche de parole de Cyber Engine Tweaks. Si vous ne regardez personne, vous parlez au premier membre de votre groupe.",
    ["Home"] = "Début",
    ["Insert"] = "Inser",
    ["Key bindings"] = "Raccourcis",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Les raccourcis demandent Codeware, que ce jeu n’a pas. Ouvrez l’Aide pour voir ce qui manque.",
    ["Key or button"] = "Touche ou bouton",
    ["Left arrow"] = "Flèche gauche",
    ["Menu"] = "Menu",
    ["No key was pressed, so nothing changed."] = "Aucune touche n’a été appuyée, donc rien n’a changé.",
    ["Not available"] = "Indisponible",
    ["Not set"] = "Non défini",
    ["Num lock"] = "Verr. Num",
    ["Page down"] = "Page suiv.",
    ["Page up"] = "Page préc.",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Appuyez dessus, puis sur la touche ou le bouton de manette voulu. Esc ou B annule. Ça marche tout de suite.",
    ["Press it to open the Companion Manager while you play."] = "Appuyez dessus pour ouvrir la gestion des compagnons pendant que vous jouez.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Appuyez dessus pour écrire au personnage devant vous. Si vous ne regardez personne, vous écrivez au premier membre de votre groupe.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Appuyez dessus pour écrire à Johnny, la voix dans votre tête, quel que soit l’endroit où vous regardez. Johnny dans votre tête doit être activé dans les Paramètres.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Appuyez dessus pour écrire à tous les personnages autour de vous en même temps. Si vous ne regardez personne, vous écrivez au premier membre de votre groupe et à deux autres membres du groupe.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Appuyez sur la touche ou le bouton de manette pour {action}. Esc ou B annule.",
    ["Print screen"] = "Impr écran",
    ["Remove the key or button you set here."] = "Retirez la touche ou le bouton que vous avez défini ici.",
    ["Right arrow"] = "Flèche droite",
    ["Scroll lock"] = "Arrêt défil.",
    ["Space"] = "Espace",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Parler par texte",
    ["Talk by voice"] = "Parler par la voix",
    ["Talk to Johnny by text"] = "Parler à Johnny par texte",
    ["Talk to Johnny by voice"] = "Parler à Johnny au micro",
    ["That key is already used for another action."] = "Cette touche est déjà utilisée pour une autre action.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Les raccourcis du mod n’ont pas pu être chargés. Ouvrez l’Aide pour voir le problème.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Les scripts du mod ne se sont pas chargés, donc aucune touche ne peut être définie. Ouvrez l’Aide pour voir le problème.",
    ["The same setting as Settings > Voices > Controller talk button."] = "Le même réglage que Paramètres > Voix > Bouton de parole manette.",
    ["Up arrow"] = "Flèche haut",
    ["View"] = "Affichage",
    ["{action} cleared."] = "{action} effacé.",
    ["{action} is set to {key}."] = "{action} est défini sur {key}.",
    ["{key} is already used for {other}. Choose another."] = "{key} est déjà utilisé pour {other}. Choisissez-en un autre.",
    ["10 minutes"] = "10 minutes",
    ["2 minutes"] = "2 minutes",
    ["5 minutes"] = "5 minutes",
    ["Cancel this meeting. She is not told."] = "Annuler le rendez-vous, sans la prévenir.",
    ["Car"] = "Voiture",
    ["Choose how long she waits."] = "Choisis combien de temps elle attend.",
    ["Choose how she arrives."] = "Choisis comment elle arrive.",
    ["Choose one of the listed options."] = "Choisis une des options proposées.",
    ["Choose when she arrives."] = "Choisis quand elle arrive.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Quand tu les invites, les compagnons viennent à pied ou en voiture, t’écrivent, attendent et s’en souviennent si tu ne viens pas.\n\nDésactivé par défaut.",
    ["Fine. Call me when you know what you want."] = "D’accord. Rappelle-moi quand tu sauras ce que tu veux.",
    ["How long she waits"] = "Combien de temps elle attend",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Combien de temps elle t’attend à son arrivée immédiate. Après une arrivée programmée, elle attend autant que le délai choisi. L’attente s’arrête pendant un combat, une scène ou un menu.",
    ["How she arrives"] = "Comment elle arrive",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "J’ai attendu {minutes} minutes à {place} et tu n’es jamais venu. Laisse tomber.",
    ["I'm here at {place}. Where are you?"] = "Je suis là, à {place}. Tu es où ?",
    ["Immersive invitations"] = "Invitations immersives",
    ["In 10 minutes"] = "Dans 10 min",
    ["In 2 minutes"] = "Dans 2 min",
    ["In 5 minutes"] = "Dans 5 min",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Invite un compagnon et elle vient vraiment à toi : elle apparaît hors de vue, arrive à pied ou en voiture, t’écrit quand elle est là et t’attend.",
    ["Meet at my waypoint when I ask"] = "Rejoindre mon point sur demande",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Désactivé : Inviter amène un compagnon à tes côtés immédiatement.\n\nActivé : un compagnon que tu invites, par le bouton Inviter, l’onglet Contacts ou un message, se rend à toi et arrive après le délai choisi ici. Elle t’écrit quand elle est là, attend et repart en colère (et s’en souvient) si tu ne viens jamais.",
    ["Right now"] = "Maintenant",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Maintenant : elle se met en route dès qu’elle est prête.\n\nDans 2, 5 ou 10 minutes : de vraies minutes de jeu, elle arrive donc à cette heure-là. Elle attend ensuite autant que ce délai.",
    ["She texts you"] = "Elle t’écrit",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Elle t’écrit à son arrivée, quand tu annules et quand elle abandonne. Désactivé : aucun message (elle se souvient quand même du lapin).",
    ["Something came up and I can't make it. Sorry."] = "Un imprévu m’empêche de venir. Désolée.",
    ["Walk"] = "À pied",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "À pied : elle apparaît hors de vue et marche jusqu’à toi.\n\nVoiture : si une route est proche, elle s’y arrête en voiture, descend et finit à pied. Sans route, elle marche. La voiture reste près de toi pour le trajet et disparaît quand elle quitte ton groupe ou que vous vous éloignez tous les deux.",
    ["When she arrives"] = "Quand elle arrive",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Si tu lui demandes de venir à ton point et qu’un repère est posé, elle y va et le dit. Désactivé : elle vient là où tu es.",
    ["Your position cannot be read yet."] = "Ta position ne peut pas encore être lue.",
    ["on her way"] = "en chemin",
    ["the meeting spot"] = "le point de rendez-vous",
    ["waiting at {place}"] = "attend à {place}",
    ["{name} is already on the way."] = "{name} est déjà en chemin.",
    ["{name} is on her way."] = "{name} est en chemin.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} est en chemin. Environ {minutes} minutes.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name} : Ravie de te voir. On y va.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Faire déménager",
    ["That companion is not available."] = "Ce compagnon n’est pas disponible.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "Vous n’avez pas cet appartement.",
    ["at home"] = "à la maison",
    ["out"] = "dehors",
    ["with you"] = "avec vous",
    ["{count} more housemates"] = "{count} colocataires de plus",
    ["{name} has moved out."] = "{name} a déménagé.",
    ["{name} is back at home."] = "{name} est de retour à la maison.",
    ["{name} joins you."] = "{name} vous rejoint.",
    ["{name} moves into {apartment}."] = "{name} emménage à {apartment}.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} ne vit plus chez vous. Le reste ne change pas.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · habite {apartment} · {state}",
    ["Companions change outfits"] = "Compagnons changent de tenue",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Les compagnons de votre groupe changent de tenue de temps en temps : un autre look le jour et la nuit, et des vêtements décontractés à la maison, quand le personnage en possède.\n\nUniquement hors de votre vue, jamais devant vous, et seulement pour les copies propres à votre groupe, jamais pour les personnages du jeu. Désactiver cette option les laisse dans la tenue qu’ils portent à ce moment-là.",
    ["Choose how often companions speak up."] = "Choisissez à quelle fréquence les compagnons prennent la parole.",
    ["Companions speak up"] = "Les compagnons prennent la parole",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example.\n\nOff: it is not sent, and nothing is read from those mods."] = "Comment va V selon les autres mods, s’ils sont installés : par exemple la fatigue, la faim, la soif, les nerfs et les addictions de Dark Future.\n\nDésactivé : rien n’est envoyé, et ces mods ne sont pas lus.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Depuis combien de temps V a parlé à ce personnage pour la dernière fois, dans le jeu et en jours réels : depuis hier soir, ou il y a des jours. Ce n’est dit que si l’écart est assez long pour compter, et pas deux fois dans la même conversation.\n\nDésactivé : rien n’est envoyé, et le mod cesse de lire l’horloge du jeu pour cela.",
    ["Music and TV"] = "Musique et TV",
    ["Other mods’ state"] = "État des autres mods",
    ["Speaks up normally"] = "Prend la parole normalement",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "La chanson diffusée à la radio de la voiture quand V roule avec le personnage, ou sur la radio de poche de V, et ce qui passe sur une TV près de V.\n\nDésactivé : rien n’est envoyé, et le mod cesse de le lire dans le jeu.",
    ["Time since last talk"] = "Temps depuis la dernière discussion",
    ["Companions in your party sometimes start talking on their own: now and then at a calm moment, and after a scene or a conversation they were part of. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often: about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Les compagnons prennent parfois la parole d’eux-mêmes : de temps en temps lors d’un moment calme, et après une scène ou une conversation à laquelle ils ont pris part. Jamais pendant les combats, scènes, appels ou menus.\n\nRarement : environ 2 par heure de jeu. Normalement : environ 4. Souvent : environ 6.\n\nQuand Johnny parle aussi, les deux fréquences s’additionnent et ils se relaient.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand répond aux touches « Parler à Johnny au micro » et « Parler à Johnny par texte », comme la voix dans la tête de V, si le récit l’y place.\n\nActivé : il répond quand on lui parle. Rarement : il parle aussi de lui-même, environ 2 par heure de jeu. Normalement : environ 4. Souvent : environ 6.\n\nQuand les compagnons parlent aussi, les deux fréquences s’additionnent et ils se relaient.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default. An off kind is not sent to any conversation provider."] = "Choisissez les infos de jeu en direct transmises aux personnages, comme le lieu, l’heure, la météo, les compagnons, la santé, l’argent, l’équipement, les quêtes, la musique et TV, et l’état des autres mods.\n\nTout est activé par défaut. Une information désactivée n’est envoyée à aucun fournisseur de conversation.",
    ["Housemates"] = "Colocataires",
    ["Housemates talk to each other"] = "Les colocataires se parlent",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Quand deux colocataires ou plus sont à la maison avec toi, ils se parlent de temps en temps.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Les personnages à qui tu dis qu’ils peuvent rester chez toi emménagent dans tes appartements et y vivent.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Les personnages à qui tu dis qu’ils peuvent rester chez toi emménagent dans tes appartements et y vivent.\n\nDésactivé par défaut.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Activé : les personnages à qui tu dis qu’ils peuvent rester chez toi emménagent dans tes appartements et y vivent, et tu peux les emmener avec toi.\n\nDésactivé : rien de tout cela ne tourne. En désactivant, ils quittent tes appartements, mais on se souvient de qui y vivait, donc ils reviennent quand tu réactives.",
}
